import React, { useContext, useEffect, useState } from 'react';
import { Modal, Button, Form, Row, Col, Alert, Spinner } from 'react-bootstrap';
import { FaBookOpen, FaBuilding, FaCalendarAlt, FaImage, FaDownload, FaExclamationCircle, FaEdit, FaTrash } from 'react-icons/fa';
import { AuthContext } from '../../App';
import {
  fetchClassSubjects,
  uploadHomeworkImage,
  createHomeworkUpload,
  fetchHomeWorkUploads,
  updateHomeworkUpload,
  deleteHomeworkUpload,
} from '../../services/HomeworkServices/homeworkServices';

function HomeworkModal(props) {
  const { stateAuth } = useContext(AuthContext);
  const user = stateAuth?.user || {};
  const [subjects, setSubjects] = useState([]);
  const [subjectId, setSubjectId] = useState('');
  const [description, setDescription] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [uploading, setUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isFetching, setIsFetching] = useState(false);
  const [homeworkList, setHomeworkList] = useState([]);
  const [fetchError, setFetchError] = useState('');
  const [alertShow, setAlertShow] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [alertVarient, setAlertVarient] = useState('');

  const instituteName = user.instnm || '';
  const branchName = user.brcnm || '';
  const academicYear = user.acdmcyr || '';
  const className = user.clsnm || '';
  const sectionName = user.secnm || '';
  const classId = user.clsid || '';
  const sectionId = user.secid || '';
  const staffId = user.stfid || '';

  useEffect(() => {
    if (props.show && classId) {
      loadSubjects();
    }
  }, [props.show, classId]);

  useEffect(() => {
    if (!props.show) {
      setSubjectId('');
      setDescription('');
      setImageUrl('');
      setAlertShow(false);
    }
  }, [props.show]);

  const loadSubjects = async () => {
    const res = await fetchClassSubjects({ clsid: classId });
    if (res && res.status === 'success' && res.payload) {
      setSubjects(res.payload || []);
    } else {
      setSubjects([]);
    }
  };

  const hideMessage = () => {
    setTimeout(() => {
      setAlertShow(false);
      setAlertMessage('');
      setAlertVarient('');
    }, 5000);
  };

  const handleImageChange = async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setUploading(true);
    const newFile = new File([file], file.name, {
      type: file.type,
      lastModified: file.lastModified,
    });
    const formData = new FormData();
    formData.append('image', newFile);
    formData.append('type', 'homework');
    formData.append('imgtyp', 'student_photo');
    const res = await uploadHomeworkImage(formData);
    setUploading(false);
    if (res && res.status === 'success' && res.payload && res.payload.url) {
      setImageUrl(res.payload.url);
      setAlertMessage('Image Uploaded Successfully');
      setAlertVarient('success');
      setAlertShow(true);
      hideMessage();
    } else {
      setAlertMessage('Failed to Upload the Image');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
    }
  };

  const handleSubmit = async () => {
    if (!description) {
      setAlertMessage('Please Enter Description');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
      return;
    }
    setIsSaving(true);
    const payload = {
      fkinstid: user.instid,
      fkbrcid: user.brcid,
      desc: description,
      fkclsid: classId,
      fksubid: subjectId,
      fksecid: sectionId,
      stfid: staffId,
      imguld: imageUrl,
      acdmcyr: academicYear,
      usrid: user.usrid,
    };
    const res = await createHomeworkUpload(payload);
    setIsSaving(false);
    if (res && res.status === 'success') {
      setAlertMessage('Home Work Upload Created Successfully');
      setAlertVarient('success');
      setAlertShow(true);
      hideMessage();
      props.onClose();
    } else {
      setAlertMessage(res?.error?.message || 'Failed to Upload Home Work');
      setAlertVarient('danger');
      setAlertShow(true);
      hideMessage();
    }
  };

  const handleFetch = async () => {
    setIsFetching(true);
    setFetchError('');
    const params = {
      typ: user.typ,
      instid: user.instid,
      brcid: user.brcid,
      clsid: user.clsid,
      secid: user.secid,
      stfid: user.stfid,
      acdmcyr: academicYear,
      usrid: user.usrid,
    };
    const res = await fetchHomeWorkUploads(params);
    setIsFetching(false);
    if (res && res.status === 'success') {
      setHomeworkList(res.payload || []);
    } else {
      setFetchError(res?.error?.message || 'Failed to Fetch Home Work');
    }
  };

  return (
    <Modal show={props.show} onHide={props.onClose} size="lg" centered>
      <Modal.Header closeButton>
        <Modal.Title className="d-flex align-items-center gap-2">
          <FaBookOpen className="text-primary" />
          Home Work Upload
        </Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <Alert
          variant={alertVarient}
          show={alertShow}
          onClose={() => setAlertShow(false)}
          dismissible
        >
          {alertMessage}
        </Alert>

        {/* Institute + Branch default from login response */}
        <div className="hw-default-card">
          <Row>
            <Col md={6}>
              <div className="hw-default-item">
                <FaBuilding className="hw-default-icon" />
                <div>
                  <span>Institute</span>
                  <strong>{instituteName || '—'}</strong>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <div className="hw-default-item">
                <FaBuilding className="hw-default-icon" />
                <div>
                  <span>Branch</span>
                  <strong>{branchName || '—'}</strong>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <div className="hw-default-item">
                <FaCalendarAlt className="hw-default-icon" />
                <div>
                  <span>Academic Year</span>
                  <strong>{academicYear || '—'}</strong>
                </div>
              </div>
            </Col>
            <Col md={6}>
              <div className="hw-default-item">
                <FaBookOpen className="hw-default-icon" />
                <div>
                  <span>Class / Section</span>
                  <strong>
                    {className || '—'} {sectionName ? `- ${sectionName}` : ''}
                  </strong>
                </div>
              </div>
            </Col>
          </Row>
        </div>

        <Form className="mt-3">
          <Form.Group className="mb-3">
            <Form.Label>Subject</Form.Label>
            <Form.Select
              value={subjectId}
              onChange={(e) => setSubjectId(e.target.value)}
            >
              <option value="">Select Subject</option>
              {subjects.map((s) => (
                <option key={s.subid} value={s.subid}>
                  {s.subnm}
                </option>
              ))}
            </Form.Select>
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Description</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              placeholder="Enter home work description..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </Form.Group>

          <Form.Group className="mb-2">
            <Form.Label>
              <FaImage className="me-1" /> Image Upload
            </Form.Label>
            <Form.Control
              type="file"
              accept=".png,.jpg,.jpeg,.bmp,.pdf"
              onChange={handleImageChange}
            />
            <Form.Text className="text-muted">
              {uploading ? 'Uploading The Image...' : ''}
            </Form.Text>
          </Form.Group>

          {imageUrl && (
            <div className="hw-image-preview">
              {imageUrl.toLowerCase().endsWith('.pdf') ? (
                <a href={imageUrl} target="_blank" rel="noreferrer">
                  View PDF
                </a>
              ) : (
                <img src={imageUrl} alt="homework" width="120" />
              )}
            </div>
          )}
        </Form>

        {fetchError && (
          <Alert variant="danger" className="mt-3 mb-0">
            <FaExclamationCircle className="me-1" /> {fetchError}
          </Alert>
        )}

        {homeworkList.length > 0 && (
          <div className="mt-4">
            <div className="d-flex justify-content-between align-items-center mb-2">
              <h6 className="mb-0">Fetched Home Work</h6>
              <span className="badge bg-secondary">{homeworkList.length} found</span>
            </div>
            <div className="hw-fetch-list">
              {homeworkList.map((hw) => (
                <div className="hw-fetch-item" key={hw.hmwkudid}>
                  <div className="hw-fetch-item-head">
                    <strong>{hw.sbnm || 'Subject'}</strong>
                    <span className="hw-fetch-date">{hw.crtdt ? new Date(hw.crtdt).toLocaleDateString() : ''}</span>
                  </div>
                  <p className="hw-fetch-desc mb-1">{hw.desc}</p>
                  <div className="hw-fetch-meta">
                    {hw.clsnm && <span className="badge bg-light text-dark me-1">{hw.clsnm}</span>}
                    {hw.senm && <span className="badge bg-light text-dark me-1">{hw.senm}</span>}
                    {hw.sbnm && <span className="badge bg-light text-dark">{hw.sbnm}</span>}
                  </div>
                  {hw.imguld && (
                    <div className="mt-2">
                      {hw.imguld.toLowerCase().endsWith('.pdf') ? (
                        <a href={hw.imguld} target="_blank" rel="noreferrer" className="btn btn-sm btn-outline-primary">
                          <FaDownload className="me-1" /> View PDF
                        </a>
                      ) : (
                        <img src={hw.imguld} alt="homework" width="90" className="rounded border" />
                      )}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </Modal.Body>
      <Modal.Footer>
        <Button variant="secondary" onClick={props.onClose}>
          Cancel
        </Button>
        <Button variant="success" onClick={handleFetch} disabled={isFetching || isSaving || uploading}>
          {isFetching ? (
            <>
              <Spinner as="span" animation="border" size="sm" role="status" aria-hidden="true" className="me-2" />
              Fetching...
            </>
          ) : (
            'Fetch'
          )}
        </Button>
        <Button variant="primary" onClick={handleSubmit} disabled={isSaving || uploading || isFetching}>
          {isSaving ? 'Uploading...' : 'Submit'}
        </Button>
      </Modal.Footer>
    </Modal>
  );
}

export default HomeworkModal;
